{
  "predictors": [
    {
      "name": "Employee Growth Rate",
      "construction": "Current employee count minus employee count from one year ago, divided by employee count from one year ago.",
      "rationale": "Firms that are expanding their workforce may be experiencing growth opportunities, potentially leading to higher future earnings.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Revenue Volatility",
      "construction": "Standard deviation of quarterly revenues over the past five years.",
      "rationale": "Firms with more stable revenue streams may be perceived as less risky, thus leading to higher investor confidence and potentially higher returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Dividend Consistency",
      "construction": "Number of consecutive years with non-decreasing dividends minus number of years with dividend cuts over the past decade.",
      "rationale": "Consistent dividend policies may signal strong cash flow management and firm stability, attracting investors seeking reliable returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Product Launch Count",
      "construction": "Number of new products launched in the past year divided by the average number of new products launched over the past five years.",
      "rationale": "Firms that are more innovative and frequently introduce new products may capture market share and drive future revenue growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Growth rate in the number of citations received by a firm's patents over the past three years.",
      "rationale": "Increasing recognition of a firm's patents may indicate valuable intellectual property, leading to competitive advantages and future profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Buying Ratio",
      "construction": "Number of insider buy transactions divided by the number of insider sell transactions over the past year.",
      "rationale": "High insider buying may signal management's confidence in the firm's future prospects, potentially leading to higher returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Concentration",
      "construction": "Revenue from the top five customers divided by total revenue, averaged over the past three years.",
      "rationale": "A more diversified customer base reduces dependency risk, potentially leading to more stable future cash flows and returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Operating Lease Commitments",
      "construction": "Total future operating lease payments reported in financial statements divided by current total assets.",
      "rationale": "Lower dependence on lease financing may indicate a stronger balance sheet and lower financial risk, potentially leading to higher returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "R&D Intensity Change",
      "construction": "Change in R&D expenditure as a percentage of sales from the previous year to the current year.",
      "rationale": "An increase in R&D spending may signal a firm's commitment to innovation and future growth prospects, potentially leading to higher returns.",
      "higher_returns_for": "positive changes"
    },
    {
      "name": "Environmental Violation Fines",
      "construction": "Total fines paid for environmental violations over the past three years divided by total revenue.",
      "rationale": "Firms with fewer environmental issues may avoid regulatory setbacks and reputational damage, resulting in more stable or higher returns.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
